SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$QDC relationship: Table 5.10.4 Coastal erosion hazard overlay$q$, 'APPLICATION', $q$Note: a material change of use that remains accepted or accepted subject to requirements and results in building work for Class 1 and/or Class 10 buildings is not subject to RO1 or RO11 (these are to be addressed at the building works stage, see Section 1.5)$q$, 'VERIFIED_VERBATIM', NULL, NULL, NULL, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/289/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Setback$q$, 'DEFINITION', $q$For a building or structure, the shortest distance, measured horizontally, between the outermost projection of the building or structure to the vertical projection of the boundary of the lot where the building or structure is.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Outermost projection$q$, 'DEFINITION', $q$The outermost part of the building or structure, other than a part that is: - a retractable blind; or - a fixed screen; or - a rainwater fitting; or - an ornamental attachment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Boundary clearance$q$, 'DEFINITION', $q$The distance between a building or structure on premises and the boundary of the premises, measured from the part of the building or structure that is closest to the boundary, other than a part that is: - an architectural or ornamental attachment; or - a rainwater fitting. Examples: - If the fascia of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between the outside of the fascia and the boundary. - If a point on the roof of a building is the part of the building that is closest to the boundary, the boundary clearance is the distance between that point on the roof and the boundary.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Site cover$q$, 'DEFINITION', $q$Of a development, the portion of the site, expressed as a percentage, that will be covered by a building or structure, measured to its outermost projection, after the development is carried out, other than a building or structure, or part of a building or structure, that is: - in a landscaped or open space area, including, for example, a gazebo or shade structure; or - a basement that is completely below ground level and used for car parking; or - the eaves of a building; or - a sun shade.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Building height$q$, 'DEFINITION', $q$If specified: - The vertical distance, measured in metres, between the ground level of the building and the highest point on the roof of the building, other than a point that is part of an aerial, chimney, flagpole or load-bearing antenna; or - the number of storeys in the building above ground level.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Storey$q$, 'DEFINITION', $q$A space within a building between two floor levels, or a floor level and a ceiling or roof: - other than: - a space containing only a lift shaft, stairway or meter room; or - a space containing only a bathroom, shower room, laundry, toilet or other sanitary compartment; or - a space containing only a combination of the things stated in (i) or (ii); or - a basement with a ceiling that is not more than one metre above ground level; and - includes: - a mezzanine; and - a roofed structured that is on, or part of, a rooftop, if the structure does not only accommodate building plant and equipment.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Partial third storey$q$, 'DEFINITION', $q$A Partial third storey has a Gross Floor Area no greater than 50% of the storey immediately below.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$def Ground level$q$, 'DEFINITION', $q$The level of the natural ground, or, if the level of the natural ground has changed, the level as lawfully changed.$q$, 'VERIFIED_VERBATIM', NULL, NULL, $q$Schedule 1, SC1.2 Administrative definitions$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/153/0/false/08-Sep-2026/false$q$, NULL, NULL);
