INSERT INTO rule_relationships (from_rule_version_id, to_rule_id, type, basis_provision_id, verification, notes) VALUES ($q$CGC.gc_ldr_side_rear_setback_height_tiered@2026-09-29$q$, $q$QDC11.A2a.SIDE_REAR_CLEARANCE$q$, 'OVERRIDES', p('QLD_BUILDING_ACT_1975@2026-02-01', 's 33'), 'VERIFIED_VERBATIM', 'Alternative provision (Building Act s33(4)): QDC applies only to the extent this provision does not. Scope must be confirmed per rule (zone/precinct/structure).');
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.1.3 Table 6.2.1-1 RO1; Table 6.2.1-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5m | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m | Between on-site habitable buildings (where not attached) | Double the applicable side setback. | OR$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.1-1 (Part A, ruleId 347) and Table 6.2.1-2 (Part B, ruleId 372)$q$, NULL, $q$Low density residential zone code (6.2.1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/37/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ldr_rear_setback_height_tiered$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ldr_rear_setback_height_tiered", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.REAR", "title": "6.2.1.3 Table 6.2.1-1 RO1; Table 6.2.1-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_REAR", "operator": ">=", "value": {"op": "unencoded", "text": "same as side: 1.5m (<=4.5m), 2m (4.5-7.5m), +0.5m per 3m or part over 7.5m", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_ldr_rear_setback_height_tiered", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"rear_setback_min\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"same as side: 1.5m (<=4.5m), 2m (4.5-7.5m), +0.5m per 3m or part over 7.5m\"}\nStructure scope 'all buildings' mapped by keyword to ['ANY']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Duplicate of side rule keyed for REAR_SETBACK topic. Table 1.5-1 (s1.5 Building work regulated under the City Plan) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ldr_rear_setback_height_tiered@2026-09-29$q$;
