SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.1.3 Table 6.2.1-1 RO1; Table 6.2.1-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Front | 6m | Side and rear | Height | Setback | up to 4.5m | 1.5m | between 4.5m – 7.5m | 2m | exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m | Between on-site habitable buildings (where not attached) | Double the applicable side setback. | OR$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.1-1 (Part A, ruleId 347) and Table 6.2.1-2 (Part B, ruleId 372)$q$, NULL, $q$Low density residential zone code (6.2.1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/37/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ldr_separation_habitable_buildings$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ldr_separation_habitable_buildings", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SEPARATION.BUILDINGS", "title": "6.2.1.3 Table 6.2.1-1 RO1; Table 6.2.1-2 AO1", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SEPARATION", "operator": ">=", "value": {"op": "unencoded", "text": "2 x applicable side setback", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_ldr_separation_habitable_buildings", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"separation_between_habitable_buildings\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": \"2 x applicable side setback\"}\nStructure scope 'on-site habitable buildings (where not attached)' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Applies to habitable buildings only - not Class 10a. Whether a separation requirement is a 'boundary clearance' alternative is unclear."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ldr_separation_habitable_buildings@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.1.3 Table 6.2.1-1 RO1 (small lots); Table 6.2.1-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks for Dwelling houses on small lots: | Setbacks | Minimum distances measured in metres (m) | Front | 4.5m to wall and balcony | Secondary frontage of corner lot | 4m (not including projections up to 2m) | Covered car parking (not applicable to the rear lane access) | 1m behind front wall or balcony; and 6m from the frontage where vehicles access the lot. | Side and rear (not applicable to the secondary frontage of corner lots) | Height | Setback | up to 4.5m | 1m to wall and balcony | 0.5m to outermost projection | 0m to class 10 buildings and/or non-habitable room where: - located along either a southern or western boundary; - a maximum length of 12m where no single part exceeds 6m in length - at least 1m separation from a habitable window of a neighbouring dwelling. | for the part between 4.5m - 7.5m | 1.5m to wall and balcony 1m to outermost projection | for that part exceeding 7.5m | 2m to wall and balcony 1.5m to outermost projection | Rear lane | 0.5m minimum 1m maximum for covered car parking | OR For development on rear lots the setback is 3m from all boundaries.$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.1-1 (Part A, ruleId 347) and Table 6.2.1-2 (Part B, ruleId 372)$q$, NULL, $q$Low density residential zone code (6.2.1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/37/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ldr_small_lot_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ldr_small_lot_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.1.3 Table 6.2.1-1 RO1 (small lots); Table 6.2.1-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": 4.5, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_1"], "sources": [{"key": "gc_ldr_small_lot_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min_wall_balcony\", \"operator\": \">=\", \"value\": 4.5, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): small lot: lot area < 400m2 (Sch 1 'Small lot')\nStructure scope 'Dwelling house on small lot (wall and balcony)' mapped by keyword to ['CLASS_1']\nAlternative provision to QDC/QHC: YES\nResearcher notes: Dwelling house on lot < 400m2 is 'accepted subject to requirements' in LDR (Table 5.5.1). Table 1.5-1 (s1.5 Building work regulated under the City Plan) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ldr_small_lot_front_setback@2026-09-29$q$;
