SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.1.3 Table 6.2.1-1 RO4; Table 6.2.1-2 PO4/AO4$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$RO4 Freestanding garages and carports do not exceed a height of 3.5m. | PO4 Free standing garages and car ports present to the street as very low rise. | AO4 Freestanding garages and carports do not exceed a height of 3.5m.$q$, 'VERIFIED_VERBATIM', $q$ruleId 364 / 393$q$, NULL, $q$Low density residential zone code (6.2.1)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/37/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_ldr_garage_carport_height$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_ldr_garage_carport_height", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "OUTBUILDING.SIZE", "title": "6.2.1.3 Table 6.2.1-1 RO4; Table 6.2.1-2 PO4/AO4", "role": "REQUIREMENT", "regime": "PLANNING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_OUTBUILDING_SIZE", "operator": "<=", "value": 3.5, "unit": "m", "on_noncompliance": "PLANNING_APPROVAL_REQUIRED", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:LOW_DENSITY_RESIDENTIAL"}], "subjects": ["CLASS_10A"], "sources": [{"key": "gc_ldr_garage_carport_height", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"freestanding_garage_carport_height_max\", \"operator\": \"<=\", \"value\": 3.5, \"unit\": \"m\", \"conditions\": [], \"exceptions\": [], \"formula_text\": null}\nStructure scope 'freestanding garages and carports' mapped by keyword to ['CLASS_10A']\nAlternative provision to QDC/QHC: UNKNOWN\nResearcher notes: Only Class 10a height limit in the zone. Applies only where the zone code is an assessment benchmark/requirement (MCU accepted subject to requirements or assessable) or, arguably, via Table 1.5-1 height alternative. No floor-area limit for sheds/outbuildings found in the zone code."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_ldr_garage_carport_height@2026-09-29$q$;
SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$6.2.2.3 Table 6.2.2-1 RO1; Table 6.2.2-2 AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m. | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR$q$, 'VERIFIED_VERBATIM', $q$Table 6.2.2-1 RO1 (ruleId 16554); Table 6.2.2-2 AO1 (ruleId 16559)$q$, NULL, $q$Medium density residential zone code (6.2.2)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/36/0/false/08-Sep-2026/false$q$, $q$Scheme definition 'Setback': shortest horizontal distance from the outermost projection of the building or structure to the vertical projection of the lot boundary. 'Outermost projection' excludes retractable blinds, fixed screens, rainwater fittings, ornamental attachments. Note: when acting as a QDC alternative provision, the building certifier may apply QDC/QHC measurement conventions (boundary clearance, also defined in Sch 1) - manual review.$q$, $q$gc_mdr_front_setback$q$);
SELECT define_rule($q${"rule_id": "CGC.gc_mdr_front_setback", "instrument_version": "CGC_CITY_PLAN@2026-09-29", "topic": "SETBACK.FRONTAGE", "title": "6.2.2.3 Table 6.2.2-1 RO1; Table 6.2.2-2 AO1", "role": "REQUIREMENT", "regime": "BUILDING", "enforceability": "DEEMED_TO_COMPLY", "provision_kind": "ACCEPTED_DEVELOPMENT_REQUIREMENT", "measurement": "SCHEME_SETBACK_FRONT", "operator": ">=", "value": {"op": "unencoded", "text": "Setbacks are as follows: | Setback | Minimum distances measured in metres (m) | Height | Setback | Front for covered car parking (excluding a basement) | all | 6m | Front (excluding covered car parking) | up to 23m | 4m | for that part exceeding 23m | 6m | Side and rear | up to 4.5m | 1.5m | for that part between 4.5m – 7.5m | 2m | for that part exceeding 7.5m | an extra 0.5m is added for every 3m in height or part thereof over 7.5m. | Between on site habitable buildings (where not attached) | Double the applicable side setback. | OR", "extracted_value": null, "extracted_operator": "formula"}, "unit": "m", "on_noncompliance": "REFERRAL_TO_LOCAL_GOVERNMENT", "effective_from": "2026-09-29", "verification": "VERIFIED_VERBATIM", "automatable": false, "scopes": [{"level": "LOCAL_GOVERNMENT", "lg": "GOLD_COAST"}, {"level": "ZONE", "zone": "CGC:MEDIUM_DENSITY_RESIDENTIAL"}], "subjects": ["ANY"], "sources": [{"key": "gc_mdr_front_setback", "role": "PRIMARY"}], "interpretation_notes": "AUTO-IMPORTED (draft). Extracted structure: {\"parameter\": \"front_setback_min\", \"operator\": \"formula\", \"value\": null, \"unit\": \"m\", \"conditions\": [\"height up to 23m: 4m\", \"part exceeding 23m: 6m\"], \"exceptions\": [], \"formula_text\": null}\nLot conditions (not encoded): standard table (non-small-lot)\nStructure scope 'buildings excluding covered car parking' mapped by keyword to ['ANY'] (default)\nAlternative provision to QDC/QHC: YES\nResearcher notes: Table 1.5-1 (s1.5 Building work regulated under the City Plan) lists 'Alternatives to QDC boundary clearance provisions' -> 'Buildings: Relevant zone code ...' (Section 33(2) BA). Applies to buildings (incl. Class 1 and Class 10a buildings). For 'Structures' only the Coastal erosion hazard and Road widening overlay codes are alternatives; 'QDC setbacks will apply to any building or structure where an alternative setback is not provided in the above codes.' Scheme refers to QDC MP1.1/MP1.2, not the QHC."}$q$::jsonb);
UPDATE rule_versions SET status = 'DRAFT' WHERE rule_version_id = $q$CGC.gc_mdr_front_setback@2026-09-29$q$;
