SELECT define_provision($q$CGC_CITY_PLAN@2026-09-29$q$, $q$RO1; PO1/AO1$q$, 'ACCEPTED_DEVELOPMENT_REQUIREMENT', $q$Buildings and structures are not located in Road widening requirement areas and are separated from future road boundaries in accordance with the relevant zone or overlay required outcomes for setbacks where the development is proposed on a lot affected by a Road widening requirement area as identified on the Road widening overlay map. Notes: - The location of the future road boundary is to be obtained from Council. - Where there are no required outcomes for setbacks in the relevant codes there are no setback requirements from the future road boundary. - Any area-based calculations under City Plan (e.g. site cover and density) can utilise the Road widening requirement area.$q$, 'VERIFIED_VERBATIM', $q$ruleId 38775 / 38685$q$, NULL, $q$Road widening overlay code (8.2.16)$q$, NULL, $q$https://cityplan.goldcoast.qld.gov.au/eplan/api/l/r/400/0/false/08-Sep-2026/false$q$, $q$Measured from future road boundary (obtain from Council).$q$, $q$gc_road_widening_setback$q$);
